addTerms([
 {id:"bpd",t:"Borderline personality disorder",la:"",d:"Psychology",b:"A pervasive pattern of instability in relationships, self-image and emotions, with marked impulsivity, beginning by early adulthood.",p:"DSM-5-TR: five or more of nine criteria (frantic efforts to avoid abandonment; unstable intense relationships; identity disturbance; impulsivity; recurrent suicidal behaviour or self-harm; affective instability; chronic emptiness; intense anger; transient stress-related paranoia or dissociation). ICD-11 replaces categories with personality disorder severity plus trait domains and a 'borderline pattern' specifier.",ex:"Rapid swings from idealising to devaluing a friend after a missed call.",where:"DSM-5-TR; ICD-11 6D10–6D11",ccc:"",conf:"Bipolar disorder (episodic, not reactive moment to moment).",rel:["emotion-regulation","dbt"],lesson:"p3l13",alias:["borderline personality disorder","BPD","personality disorder","emotionally unstable personality"]},
 {id:"dbt",t:"Dialectical behaviour therapy (DBT)",la:"",d:"Psychology",b:"A therapy for emotion dysregulation, combining acceptance (mindfulness, validation) with change (skills, behaviour analysis).",p:"Developed by Marsha Linehan. Four skill modules: mindfulness, distress tolerance, emotion regulation, interpersonal effectiveness; delivered through individual therapy, skills group, phone coaching and therapist consultation. Reduced self-harm vs treatment as usual in BPD (Storebø et al., 2020).",ex:"Using 'opposite action' when anger urges an attack.",where:"Linehan (1993); Storebø et al. (2020)",ccc:"",conf:"Generic CBT.",rel:["bpd","emotion-regulation"],lesson:"p3l13",alias:["DBT","dialectical behaviour therapy","dialectical behavior therapy","wise mind"]},
 {id:"psychopathy",t:"Psychopathy",la:"",d:"Psychology",b:"A personality constellation of interpersonal charm and manipulation, shallow affect, lack of remorse and empathy, and impulsive, antisocial lifestyle.",p:"Cleckley (1941); operationalised by Hare's Psychopathy Checklist–Revised (PCL-R), 20 items scored 0–2, with an interpersonal/affective factor and a lifestyle/antisocial factor. Not a DSM diagnosis (overlaps antisocial personality disorder). General population prevalence about 1.2% with the PCL-R, 4.5% across instruments (Sanz-García et al., 2021).",ex:"A charming fraudster who expresses no guilt for ruining his victims.",where:"Hare (2003); Skeem et al. (2011)",ccc:"",conf:"Psychosis; antisocial personality disorder (broader, behaviour-based).",rel:["imputability","synderesis"],lesson:"p3l14",alias:["psychopathy","psychopath","PCL-R","antisocial personality","callous-unemotional"]},
 {id:"eating-disorder",t:"Eating disorders",la:"",d:"Psychology",b:"Serious mental disorders of eating behaviour and body-related thinking, including anorexia nervosa, bulimia nervosa and binge-eating disorder.",p:"Anorexia nervosa: restriction leading to significantly low body weight, intense fear of weight gain, disturbed body experience. Bulimia nervosa: recurrent binge eating with compensatory behaviours and self-evaluation unduly based on shape and weight. Binge-eating disorder: recurrent binges without regular compensation. Anorexia has among the highest mortality of psychiatric disorders.",ex:"A first-year student whose life is increasingly ruled by rules about food and body checking.",where:"DSM-5-TR; ICD-11 6B80–6B82",ccc:"2288–2290",conf:"Ordinary dieting; religious fasting (moderated by reason and Church discipline).",rel:["temperance"],lesson:"p3l15",alias:["eating disorder","anorexia","bulimia","binge eating","ARFID"]},
 {id:"cbt-i",t:"CBT for insomnia (CBT-I)",la:"",d:"Psychology",b:"The first-line treatment for chronic insomnia: stimulus control, sleep scheduling (restriction), cognitive therapy, and sleep hygiene.",p:"Meta-analysis of 87 RCTs: large effect on insomnia severity (g = 0.98) and moderate effects on sleep efficiency and sleep onset latency (van Straten et al., 2018). Face-to-face treatment of at least four sessions appeared more effective than self-help.",ex:"Getting out of bed after about 20 minutes awake and returning only when sleepy.",where:"van Straten et al. (2018)",ccc:"",conf:"Sleep hygiene alone, which is weak on its own.",rel:["sorrow"],lesson:"p3l16",alias:["CBT-I","insomnia","sleep restriction","stimulus control","sleep hygiene"]}
]);

